import { cn } from '../utils/cn'
import type { Variants } from 'motion/react'
import { motion, useAnimation } from 'motion/react'
import type { HTMLAttributes } from 'react'
import React, {
  forwardRef,
  useCallback,
  useImperativeHandle,
  useRef,
} from 'react'

export interface CircleCheckBigIconHandle {
  startAnimation: () => void
  stopAnimation: () => void
}

interface CircleCheckBigIconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number
}

const CIRCLE_VARIANTS: Variants = {
  normal: {
    pathLength: 1,
    transition: { duration: 0.3 },
  },
  animate: {
    pathLength: [0, 1],
    transition: {
      duration: 0.5,
      ease: 'easeInOut',
    },
  },
}

const CHECK_VARIANTS: Variants = {
  normal: {
    opacity: 1,
    pathLength: 1,
    transition: {
      duration: 0.3,
      opacity: { duration: 0.1 },
    },
  },
  animate: {
    opacity: [0, 1],
    pathLength: [0, 1],
    transition: {
      duration: 0.35,
      delay: 0.45,
      opacity: { duration: 0.05 },
    },
  },
}

const CircleCheckBigIcon = forwardRef<
  CircleCheckBigIconHandle,
  CircleCheckBigIconProps
>(({ onMouseEnter, onMouseLeave, className, size = 24, ...props }, ref) => {
  const controls = useAnimation()
  const isControlledRef = useRef(false)

  useImperativeHandle(ref, () => {
    isControlledRef.current = true
    return {
      startAnimation: () => controls.start('animate'),
      stopAnimation: () => controls.start('normal'),
    }
  })

  const handleMouseEnter = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      if (isControlledRef.current) {
        onMouseEnter?.(e)
      } else {
        controls.start('animate')
      }
    },
    [controls, onMouseEnter],
  )

  const handleMouseLeave = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      if (isControlledRef.current) {
        onMouseLeave?.(e)
      } else {
        controls.start('normal')
      }
    },
    [controls, onMouseLeave],
  )

  return (
    <div
      className={cn(className)}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      {...props}
    >
      <svg
        fill="none"
        height={size}
        stroke="currentColor"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth="2"
        viewBox="0 0 24 24"
        width={size}
        xmlns="http://www.w3.org/2000/svg"
      >
        <motion.path
          animate={controls}
          d="M21.801 10A10 10 0 1 1 17 3.335"
          initial="normal"
          variants={CIRCLE_VARIANTS}
          style={{ pathLength: 1 }}
        />
        <motion.path
          animate={controls}
          d="m9 11 3 3L22 4"
          initial="normal"
          variants={CHECK_VARIANTS}
          style={{ pathLength: 1 }}
        />
      </svg>
    </div>
  )
})

CircleCheckBigIcon.displayName = 'CircleCheckBigIcon'

export { CircleCheckBigIcon }
