import { cn } from '../utils/cn'
import type { Variants } from 'motion/react'
import { motion, useAnimation } from 'motion/react'
import type { HTMLAttributes } from 'react'
import React, {
  forwardRef,
  useCallback,
  useImperativeHandle,
  useRef,
} from 'react'

export interface DatabaseIconHandle {
  startAnimation: () => void
  stopAnimation: () => void
}

interface DatabaseIconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number
}

const createPathVariants = (delay: number, duration = 0.4): Variants => ({
  normal: {
    opacity: 1,
    pathLength: 1,
    transition: { duration: 0.2 },
  },
  animate: {
    opacity: [0, 1],
    pathLength: [0, 1],
    transition: {
      duration,
      delay,
      opacity: { duration: 0.05 },
    },
  },
})

const DatabaseIcon = forwardRef<DatabaseIconHandle, DatabaseIconProps>(
  ({ onMouseEnter, onMouseLeave, className, size = 24, ...props }, ref) => {
    const controls = useAnimation()
    const isControlledRef = useRef(false)

    useImperativeHandle(ref, () => {
      isControlledRef.current = true
      return {
        startAnimation: () => controls.start('animate'),
        stopAnimation: () => controls.start('normal'),
      }
    })

    const handleMouseEnter = useCallback(
      (e: React.MouseEvent<HTMLDivElement>) => {
        if (isControlledRef.current) {
          onMouseEnter?.(e)
        } else {
          controls.start('animate')
        }
      },
      [controls, onMouseEnter],
    )

    const handleMouseLeave = useCallback(
      (e: React.MouseEvent<HTMLDivElement>) => {
        if (isControlledRef.current) {
          onMouseLeave?.(e)
        } else {
          controls.start('normal')
        }
      },
      [controls, onMouseLeave],
    )

    return (
      <div
        className={cn(className)}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...props}
      >
        <svg
          fill="none"
          height={size}
          stroke="currentColor"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth="2"
          viewBox="0 0 24 24"
          width={size}
          xmlns="http://www.w3.org/2000/svg"
        >
          <motion.path
            animate={controls}
            d="M 3 5 a 9 3 0 1 1 18 0 a 9 3 0 1 1 -18 0"
            initial="normal"
            variants={createPathVariants(0, 0.35)}
          />
          <motion.path
            animate={controls}
            d="M3 5V19A9 3 0 0 0 21 19V5"
            initial="normal"
            variants={createPathVariants(0.3, 0.45)}
          />
          <motion.path
            animate={controls}
            d="M3 12A9 3 0 0 0 21 12"
            initial="normal"
            variants={createPathVariants(0.6, 0.35)}
          />
        </svg>
      </div>
    )
  },
)

DatabaseIcon.displayName = 'DatabaseIcon'

export { DatabaseIcon }
