import { cn } from '../utils/cn'
import type { Variants } from 'motion/react'
import { motion, useAnimation } from 'motion/react'
import type { HTMLAttributes } from 'react'
import React, {
  forwardRef,
  useCallback,
  useImperativeHandle,
  useRef,
} from 'react'

export interface ListIconHandle {
  startAnimation: () => void
  stopAnimation: () => void
}

interface ListIconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number
}

const createLineVariants = (delay: number): Variants => ({
  normal: {
    opacity: 1,
    pathLength: 1,
    transition: { duration: 0.2 },
  },
  animate: {
    opacity: [0, 1],
    pathLength: [0, 1],
    transition: {
      duration: 0.25,
      delay,
      opacity: { duration: 0.05 },
    },
  },
})

const LINE_DELAYS = [0, 0.06, 0.12, 0.18, 0.24, 0.3]

const ListIcon = forwardRef<ListIconHandle, ListIconProps>(
  ({ onMouseEnter, onMouseLeave, className, size = 24, ...props }, ref) => {
    const controls = useAnimation()
    const isControlledRef = useRef(false)

    useImperativeHandle(ref, () => {
      isControlledRef.current = true
      return {
        startAnimation: () => controls.start('animate'),
        stopAnimation: () => controls.start('normal'),
      }
    })

    const handleMouseEnter = useCallback(
      (e: React.MouseEvent<HTMLDivElement>) => {
        if (isControlledRef.current) {
          onMouseEnter?.(e)
        } else {
          controls.start('animate')
        }
      },
      [controls, onMouseEnter],
    )

    const handleMouseLeave = useCallback(
      (e: React.MouseEvent<HTMLDivElement>) => {
        if (isControlledRef.current) {
          onMouseLeave?.(e)
        } else {
          controls.start('normal')
        }
      },
      [controls, onMouseLeave],
    )

    return (
      <div
        className={cn(className)}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...props}
      >
        <svg
          fill="none"
          height={size}
          stroke="currentColor"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth="2"
          viewBox="0 0 24 24"
          width={size}
          xmlns="http://www.w3.org/2000/svg"
        >
          <motion.path
            animate={controls}
            d="M3 5h.01"
            initial="normal"
            variants={createLineVariants(LINE_DELAYS[0])}
          />
          <motion.path
            animate={controls}
            d="M3 12h.01"
            initial="normal"
            variants={createLineVariants(LINE_DELAYS[1])}
          />
          <motion.path
            animate={controls}
            d="M3 19h.01"
            initial="normal"
            variants={createLineVariants(LINE_DELAYS[2])}
          />
          <motion.path
            animate={controls}
            d="M8 5h13"
            initial="normal"
            variants={createLineVariants(LINE_DELAYS[3])}
          />
          <motion.path
            animate={controls}
            d="M8 12h13"
            initial="normal"
            variants={createLineVariants(LINE_DELAYS[4])}
          />
          <motion.path
            animate={controls}
            d="M8 19h13"
            initial="normal"
            variants={createLineVariants(LINE_DELAYS[5])}
          />
        </svg>
      </div>
    )
  },
)

ListIcon.displayName = 'ListIcon'

export { ListIcon }
